def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    border = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    # Fill background cells strictly inside any rectangular outline of border color.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if (all(grid[r1][c] == border and grid[r2][c] == border for c in range(c1, c2 + 1)) and
